    const ref = maybe_ref orelse return null;
    return @ptrCast(ref);
}
fn _preview_mtl_signal_bridge(ctx: *anyopaque, slot: u32) anyerror!void {
    const p: *engine.Preview = @ptrCast(@alignCast(ctx));
