        fn decode(
            file_type: [:0]const u8,
            data: []const u8,
            alloc: std.mem.Allocator,
        ) anyerror!engine.DecodedImage {
            if (comptime supports_compressed) {
                if (BackendGfx.isCompressed(data)) {
                    const dims = BackendGfx.compressedDims(data) orelse return error.LoadFailed;
                    return .{ .pixels = try alloc.dupe(u8, data), .width = dims.width, .height = dims.height, .compressed = true };
                }
            }
            const d = try BackendGfx.decodeImage(file_type, data, alloc);
            return .{ .pixels = d.pixels, .width = d.width, .height = d.height };
        }
    
        fn upload(decoded: engine.DecodedImage) anyerror!engine.AssetTexture {
            var handle: u32 = MAX_IMAGE_ASSETS;
            for (slots, 0..) |slot, i| {
                if (slot == null) {
                    handle = @intCast(i);
                    break;
                }
            }
            if (handle == MAX_IMAGE_ASSETS) return error.ImageSlotsExhausted;
            const tex = blk: {
                if (comptime supports_compressed) {
                    if (decoded.compressed) break :blk try BackendGfx.uploadCompressed(decoded.pixels);
                }
                break :blk try BackendGfx.uploadTexture(.{
                    .pixels = decoded.pixels,
                    .width = decoded.width,
                    .height = decoded.height,
                });
            };
            slots[handle] = tex;
            const out_handle = handle + CATALOG_ID_BASE;
            if (renderer_ref) |r| r.registerCatalogTexture(out_handle, tex);
            return out_handle;
        }
    
        fn unload(texture: engine.AssetTexture) void {
            if (texture < CATALOG_ID_BASE) return;
            const idx = texture - CATALOG_ID_BASE;
            if (idx >= MAX_IMAGE_ASSETS) return;
            if (slots[idx]) |tex| {
                routed: {
                    if (comptime @hasDecl(Renderer, "unloadTexture")) {
                        if (renderer_ref) |r| {
                            const Param = @typeInfo(@TypeOf(Renderer.unloadTexture)).@"fn".params[1].type.?;
                            const typed: Param = if (comptime @typeInfo(Param) == .@"enum") @enumFromInt(texture) else @intCast(texture);
                            r.unloadTexture(typed);
                            break :routed;
                        }
                    }
                    BackendGfx.unloadTexture(tex);
                }
                slots[idx] = null;
            }
        }
    };
    engine.ImageLoader.setBackend(.{
        .decode = ImageBackendAdapter.decode,
        .upload = ImageBackendAdapter.upload,
        .unload = ImageBackendAdapter.unload,
    });
    ImageBackendAdapter.renderer_ref = g.renderer;

    runner = Runner.init(allocator, &g.active_world.ecs_backend);
    runner.setup(&g);
    @import("backend_input").initAndroidGamepad();
}
export fn frame() callconv(.c) void {
    const dt: f32 = 0.016;
        const scaled_dt = dt * g.time_scale;
        if (scaled_dt > 0) {
            runner.tick(&g, scaled_dt);
        }
        g.dispatchEvents();
        if (comptime @TypeOf(runner).profiling_enabled) {
            g.script_profile_ptr = @ptrCast(@alignCast(&runner.profile));
            g.script_profile_count = @TypeOf(runner).script_count;
        }
    g.tick(dt);
    g.render();
}
export fn cleanup() callconv(.c) void {
    runner.deinit();
    g.deinit();
}
export fn sokol_main(argc: c_int, argv: [*][*:0]u8) window.Desc {
    _ = argc;
    _ = argv;
    return window.makeDesc(.{ .init_cb = &init });
}
